namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// C is N x N (i x j), row-major: j is the inner (contiguous) dimension
	DEFINE_PROTO_STRUCT(c_layout, j_vec ^ i_vec);
	// A is N x M (i x k), row-major: k is the inner (contiguous) dimension
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
	// B is N x M (i x k), row-major: k is the inner (contiguous) dimension
	DEFINE_PROTO_STRUCT(b_layout, k_vec ^ i_vec);
} tuning;

