	beta  = (num_t)1.2;

	const std::size_t n = C | get_length<'i'>(); // N
	const std::size_t m = A | get_length<'k'>(); // M

	// A[i][k] = ((i*k + 1) % n) / n
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = (num_t)((i * k + 1) % n) / (num_t)n;
	});

	// B[i][k] = ((i*k + 2) % m) / m
	traverser(B).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		B[state] = (num_t)((i * k + 2) % m) / (num_t)m;
	});

	// C[i][j] = ((i*j + 3) % n) / m
	traverser(C).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		C[state] = (num_t)((i * j + 3) % n) / (num_t)m;
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_syr2k(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// BLAS-like params:
	// UPLO = 'L', TRANS = 'N'
	// A is N x M, B is N x M, C is N x N (only lower triangle updated)

	#pragma scop
	// Outer loop over i
	traverser(C, A, B).template for_dims<'i'>([=](auto inner) {
		// First: for j <= i, scale C[i][j] by beta
		inner.template for_each<'j'>([=](auto state) {
			auto [i, j] = get_indices<'i', 'j'>(state);
			if (j <= i)
				C[state] *= beta;
		});

		// Second: for k, for j <= i, perform the rank-2k update
		inner.for_each([=](auto state) {
			auto [i, j] = get_indices<'i', 'j'>(state);
			if (j <= i) {
				// state has indices (i, j, k); we also need row j of A and B
				auto state_j = state.template with<index_in<'i'>>(j);

				// C[i][j] += A[j][k]*alpha*B[i][k] + B[j][k]*alpha*A[i][k]
				C[state] +=
					A[state_j] * alpha * B[state] +
					B[state_j] * alpha * A[state];
			}
		});
	});
	#pragma endscop
}

