#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "syr2k.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// C: i x j  (N x N), row-major => j inner, i outer
	DEFINE_PROTO_STRUCT(c_layout, j_vec ^ i_vec);
	// A: i x k  (N x M), row-major => k inner, i outer
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
	// B: i x k  (N x M), row-major => k inner, i outer
	DEFINE_PROTO_STRUCT(b_layout, k_vec ^ i_vec);
} tuning;

// initialization function
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	// C: i x j  (N x N)
	// A: i x k  (N x M)
	// B: i x k  (N x M)
	using namespace noarr;

	alpha = (num_t)1.5;
	beta = (num_t)1.2;

	// retrieve logical sizes
	auto n = C | get_length<'i'>();
	auto m = A | get_length<'k'>();

	// Initialize A: A[i][k] = (i*k+1)%n / n;
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = (num_t)((i * k + 1) % n) / (num_t)n;
	});

	// Initialize B: B[i][k] = (i*k+2)%m / m;
	traverser(B).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		B[state] = (num_t)((i * k + 2) % m) / (num_t)m;
	});

	// Initialize C: C[i][j] = (i*j+3)%n / m;
	traverser(C).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		C[state] = (num_t)((i * j + 3) % n) / (num_t)m;
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_syr2k(num_t alpha, num_t beta, auto C, auto A, auto B) {
	// BLAS params:
	// UPLO = 'L'
	// TRANS = 'N'
	// A is N x M
	// B is N x M
	// C is N x N
	using namespace noarr;

	auto m = A | get_length<'k'>();

	#pragma scop
	// Scale lower triangular part of C by beta: for i, for j <= i
	traverser(C).template for_dims<'i'>([=](auto trav_i) {
		// trav_i has 'i' fixed, iterates over 'j'
		trav_i.for_each([=](auto state) {
			auto i = get_index<'i'>(state);
			auto j = get_index<'j'>(state);

			if (j <= i) {
				C[state] *= beta;
			}
		});
	});

	// Update C with symmetric rank-2k operation:
	// for i in 0..N-1
	//   for k in 0..M-1
	//     for j in 0..i
	//       C[i][j] += A[j][k]*alpha*B[i][k] + B[j][k]*alpha*A[i][k];
	//
	// We model the (i, k, j) domain by broadcasting C over a 'k' dimension.
	traverser(C).order(bcast<'k'>(m)).template for_dims<'i'>([=](auto trav_i) {
		// trav_i has 'i' fixed, iterates over 'j' and 'k'
		trav_i.template for_dims<'k'>([=](auto trav_ik) {
			// trav_ik has 'i' and 'k' fixed, iterates over 'j'
			trav_ik.for_each([=](auto state) {
				auto i = get_index<'i'>(state);
				auto j = get_index<'j'>(state);

				if (j <= i) {
					auto k = get_index<'k'>(state);

					// A[i][k] and B[i][k]: use 'i' and 'k' from current state
					auto aik = A[state];
					auto bik = B[state];

					// A[j][k] and B[j][k]: build a state with row index j
					auto state_jk = idx<'i', 'k'>(j, k);
					auto ajk = A[state_jk];
					auto bjk = B[state_jk];

					C[state] += ajk * alpha * bik + bjk * alpha * aik;
				}
			});
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t m = M;

	// input scalars
	num_t alpha;
	num_t beta;

	// set common logical lengths of dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n) ^
		noarr::set_length<'k'>(m);

	// allocate data bags with chosen layouts
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_syr2k(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to inhibit dead-code elimination in benchmarking setups)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, C.get_ref() ^ noarr::hoist<'i'>());
	}

	// print elapsed time
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}

#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "syr2k.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// C is N x N: dimensions i (rows) and j (columns)
	DEFINE_PROTO_STRUCT(c_layout, j_vec ^ i_vec);
	// A is N x M: dimensions i (rows) and k (columns)
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
	// B is N x M: dimensions i (rows) and k (columns)
	DEFINE_PROTO_STRUCT(b_layout, k_vec ^ i_vec);
} tuning;

// Array initialization
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	// C: i x j (N x N)
	// A: i x k (N x M)
	// B: i x k (N x M)
	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	// Initialize A and B
	traverser(A, B).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);

		auto n = A | get_length<'i'>(); // number of rows (N)
		auto m = B | get_length<'k'>(); // number of columns (M)

		A[state] = (num_t)((i * k + 1) % n) / n;
		B[state] = (num_t)((i * k + 2) % m) / m;
	});

	// Initialize C
	traverser(C).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		auto n = C | get_length<'i'>(); // N
		auto m = B | get_length<'k'>(); // M (denominator in original code)

		C[state] = (num_t)((i * j + 3) % n) / m;
	});
}

// Main computational kernel
[[gnu::flatten, gnu::noinline]]
void kernel_syr2k(num_t alpha, num_t beta, auto C, auto A, auto B) {
	// BLAS SYR2K:
	// C := alpha * A * B^T + alpha * B * A^T + beta * C
	// A, B are N x M; C is N x N; only the lower triangle (i >= j) is updated.
	using namespace noarr;

	// Views of A and B where the row dimension is named 'j' instead of 'i'.
	// This lets us use a single state with dimensions ('i','j','k') and get:
	//   A_j[state] -> A[j][k]
	//   B_j[state] -> B[j][k]
	//   A[state]   -> A[i][k]
	//   B[state]   -> B[i][k]
	auto A_j = A.get_ref() ^ noarr::rename<'i', 'j'>();
	auto B_j = B.get_ref() ^ noarr::rename<'i', 'j'>();

	#pragma scop
	traverser(C, A, B).template for_dims<'i'>([=](auto inner) {
		// First: C[i][j] *= beta for all j <= i (lower triangle)
		inner.template for_each<'j'>([=](auto state) {
			auto [i, j] = get_indices<'i', 'j'>(state);
			if (j <= i) {
				C[state] *= beta;
			}
		});

		// Then: C[i][j] += A[j][k]*alpha*B[i][k] + B[j][k]*alpha*A[i][k]
		// for all k and for j <= i
		inner.for_each([=](auto state) {
			auto [i, j, k] = get_indices<'i', 'j', 'k'>(state);
			if (j <= i) {
				C[state] += A_j[state] * alpha * B[state]
				          + B_j[state] * alpha * A[state];
			}
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem sizes
	std::size_t n = N;
	std::size_t m = M;

	// Scalars
	num_t alpha;
	num_t beta;

	// Lengths for all dimensions
	auto set_lengths = noarr::set_length<'i'>(n)
	                 ^ noarr::set_length<'j'>(n)
	                 ^ noarr::set_length<'k'>(m);

	// Data bags (structures + storage)
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// Initialize arrays
	init_array(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_syr2k(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Optionally print result to stderr (prevents dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// Print C in row-major order (i-hoisted view)
		noarr::serialize_data(std::cerr, C.get_ref() ^ noarr::hoist<'i'>());
	}

	// Print timing to stdout
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
